+void RendererRD::MotionBlur::motion_blur_compute(Ref<RenderSceneBuffersRD> p_render_buffers, RID p_camera_attributes, RenderSceneDataRD *p_scene_data, bool p_transparent_bg, float p_time_step, CopyEffects *p_copy_effects) {
+	if (!RSG::camera_attributes->camera_attributes_get_motion_blur_show_in_editor() && Engine::get_singleton()->is_editor_hint()) {
+		return;
+	}
+
+	Size2i base_size = p_render_buffers->get_internal_size();
+	Size2i tiled_size = Size2i(Math::division_round_up(base_size.width, tile_size), Math::division_round_up(base_size.height, tile_size));
+	uint32_t view_count = p_render_buffers->get_view_count();
+
+	if (!p_render_buffers->has_texture(RB_SCOPE_MOTION_BLUR, RB_TEX_BLUR_OUTPUT)) {
+		int usage_bits = RD::TEXTURE_USAGE_SAMPLING_BIT | RD::TEXTURE_USAGE_STORAGE_BIT;
+
+		p_render_buffers->create_texture(RB_SCOPE_MOTION_BLUR, RB_TEX_CUSTOM_VELOCITY, RD::DATA_FORMAT_R16G16B16A16_SFLOAT, usage_bits, RD::TEXTURE_SAMPLES_1, base_size);
+		p_render_buffers->create_texture(RB_SCOPE_MOTION_BLUR, RB_TEX_NEIGHBOR_MAX, RD::DATA_FORMAT_R8G8_SINT, usage_bits, RD::TEXTURE_SAMPLES_1, Size2i(tiled_size.x, base_size.y));
+		p_render_buffers->create_texture(RB_SCOPE_MOTION_BLUR, RB_TEX_TILE_MAX_Y, RD::DATA_FORMAT_R8G8_SINT, usage_bits, RD::TEXTURE_SAMPLES_1, tiled_size);
+		p_render_buffers->create_texture(RB_SCOPE_MOTION_BLUR, RB_TEX_BLUR_OUTPUT, RD::DATA_FORMAT_R16G16B16A16_SFLOAT, usage_bits, RD::TEXTURE_SAMPLES_1, base_size);
+
+		// Skip first frame, without a previous frame we cannot compute the camera velocity.
+		return;
+	}
+
+	MotionBlurBuffers buffers;
+	buffers.base_size = base_size;
+	buffers.tiled_size = tiled_size;
+
+	{
+		int sample_count;
+		switch (RSG::camera_attributes->camera_attributes_get_motion_blur_quality()) {
+			case RSE::MOTION_BLUR_QUALITY_STANDARD:
+				sample_count = 2;
+				break;
+			case RSE::MOTION_BLUR_QUALITY_HIGH:
+				sample_count = 4;
+				break;
+			case RSE::MOTION_BLUR_QUALITY_CINEMATIC:
+				sample_count = 8;
+				break;
+			default:
+				WARN_PRINT_ONCE("Unknown motion blur quality setting, defaulting to standard.");
+				sample_count = 2;
+				break;
+		}
+
+		float velocity_threshold_lower = CLAMP(RSG::camera_attributes->camera_attributes_get_motion_blur_velocity_threshold_lower(p_camera_attributes) / 100.0f, 0.0f, 1.0f);
+		float velocity_threshold_upper = CLAMP(RSG::camera_attributes->camera_attributes_get_motion_blur_velocity_threshold_upper(p_camera_attributes) / 100.0f, 0.0f, 1.0f);
+
+		// TODO: add these multipliers to settings
+		motion_blur.preprocess_push_constant.velocity_multiplier_camera_movement = RSG::camera_attributes->camera_attributes_get_motion_blur_velocity_multiplier_camera_movement(p_camera_attributes);
+		motion_blur.preprocess_push_constant.velocity_multiplier_camera_rotation = RSG::camera_attributes->camera_attributes_get_motion_blur_velocity_multiplier_camera_rotation(p_camera_attributes);
+		motion_blur.preprocess_push_constant.velocity_multiplier_object = RSG::camera_attributes->camera_attributes_get_motion_blur_velocity_multiplier_object(p_camera_attributes);
